using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace Synkoz {static class PreviewIconsR9 {
public static void Set(Button b,int kind){if(b.Image==null){var image=new Bitmap(18,18);using(var g=Graphics.FromImage(image))using(var p=new Pen(Color.FromArgb(40,65,85),1.6f)){g.SmoothingMode=SmoothingMode.AntiAlias;switch(kind){case 0:g.FillPolygon(Brushes.SteelBlue,new[]{new Point(4,2),new Point(15,9),new Point(4,16)});break;case 1:g.FillRectangle(Brushes.SteelBlue,4,3,3,12);g.FillRectangle(Brushes.SteelBlue,11,3,3,12);break;case 2:g.DrawRectangle(p,2,2,14,14);g.DrawRectangle(p,5,2,8,5);g.DrawRectangle(p,5,10,8,6);break;case 3:g.FillRectangle(Brushes.Firebrick,4,4,10,10);break;case 4:g.DrawEllipse(p,1,10,5,5);g.DrawEllipse(p,11,10,5,5);g.DrawLine(p,4,12,14,2);g.DrawLine(p,14,12,4,2);break;case 5:g.DrawArc(p,3,3,12,12,35,295);g.DrawLines(p,new[]{new Point(11,1),new Point(15,4),new Point(11,6)});break;case 6:g.DrawEllipse(p,4,4,10,10);g.DrawEllipse(p,7,7,4,4);for(int i=0;i<8;i++){double a=i*Math.PI/4;g.DrawLine(p,9+(float)Math.Cos(a)*5,9+(float)Math.Sin(a)*5,9+(float)Math.Cos(a)*8,9+(float)Math.Sin(a)*8);}break;default:foreach(int x in new[]{2,16})foreach(int y in new[]{2,16}){int dx=x==2?5:-5,dy=y==2?5:-5;g.DrawLine(p,x,y,x+dx,y);g.DrawLine(p,x,y,x,y+dy);}break;}}b.Image=image;b.Disposed+=delegate{image.Dispose();};}b.Text="";}
}}
